"""Current engineering extension, rendered exclusively through the PDF suite."""
def extension(document,section,report):
    m=report('research-metrics')['metrics'];n=report('graph-neural');g=report('github-live')
    link=lambda url,label:'<a href="'+url+'" color="#492AFF">'+label+'</a>'
    sources=[
        ['Источник','Назначение'],
        ['GraphSAGE / Hamilton et al., 2017',link('https://arxiv.org/abs/1706.02216','Inductive Representation Learning on Large Graphs')],
        ['ETS / Livingston, 2014',link('https://www.ets.org/Media/Research/pdf/LIVINGSTON2ed.pdf','Equating Test Scores, second edition')],
        ['O*NET / USDOL',link('https://www.onetonline.org/link/summary/15-1252.00','Software Developers')+'; '+link('https://www.onetonline.org/link/summary/15-2051.00','Data Scientists')+'; '+link('https://www.onetonline.org/link/summary/15-1243.01','Data Warehousing Specialists')],
        ['O*NET / лицензия',link('https://www.onetcenter.org/license_db.html','Условия использования базы и атрибуция')],
        ['GitHub / REST',link('https://docs.github.com/en/rest/pulls/pulls','Pull requests')+'; '+link('https://docs.github.com/en/rest/commits/commits','Commits')+'; '+link('https://docs.github.com/en/rest/issues/comments','Conversation comments')],
        ['GitHub / GraphQL',link('https://docs.github.com/en/graphql/guides/using-the-graphql-api-for-discussions','Repository Discussions')],
        ['GitHub / API policy',link('https://docs.github.com/en/rest/using-the-rest-api/rate-limits-for-the-rest-api','Rate limits')+'; '+link('https://docs.github.com/en/site-policy/github-acceptable-use-policies','Acceptable use')],
        ['MOEX / ISS',link('https://www.moex.com/a2193','API и договорные условия использования')],
        ['Калибровка / Guo et al., 2017',link('https://proceedings.mlr.press/v70/guo17a.html','On Calibration of Modern Neural Networks')],
        ['Proper scores / Gneiting & Raftery, 2007',link('https://sites.stat.washington.edu/people/raftery/Research/PDF/Gneiting2007jasa.pdf','Strictly Proper Scoring Rules, Prediction, and Estimation')],
        ['MOEX / сессионность истории',link('https://www.moex.com/n92946','Изменения публикации итогов по индексам, 20.08.2025')],
    ]
    import json,xml.etree.ElementTree as ET
    from pathlib import Path
    root=Path(__file__).resolve().parents[1]
    suites=[]
    for filename,label in [('research-all-cpu.xml','CPU и security HTTP'),('research-regression-http.xml','Регрессионные HTTP'),('research-http.xml','Сквозные public contribution HTTP')]:
        data=ET.parse(root/'validation/reports/current'/filename).getroot()
        suite=data.find('testsuite') if data.tag=='testsuites' else data
        assert int(suite.attrib['failures'])==int(suite.attrib['errors'])==0
        suites.append([label,suite.attrib['tests'],'0 failures / 0 errors'])
    load=report('research-load');qa=json.loads((root/'web/src/locales/qa-status.json').read_text(encoding='utf-8'))
    locale_rows=[['Язык','Ключи UI','Готовность']]
    for key in ('en','kk','uz','az','be'):
        status=qa['languages'][key]
        locale_rows.append([key,str(status['catalog_key_count'])+'/'+str(status['source_key_count']),'critical-copy gate' if status.get('critical_ready') else 'draft / не включён'])
    final=report('finalization-metrics')
    assert final['passed']
    return document('12_Contribution_and_Decision_Science','Личный вклад и наука кадрового решения','Версионированное доказательство, ролевой критерий и неопределённость в едином контуре.',[
        section('1. Инженерная композиция','Платформа соединяет независимые виды информации: публичный артефакт разработки, проверку знаний роли, наблюдаемую практику, текущие условия вакансии и явно выраженные намерения обеих сторон. Каждый слой имеет собственный знаменатель, происхождение и область применимости. Математическая оценка не превращает предположение в факт квалификации.','Rust выполняет identity, ownership, транзакционные переходы и аудит. CPU Intelligence получает ограниченный набор данных без доступа к PostgreSQL. Внешний GitHub gateway не выполняет код и не принимает произвольный URL API. Ролевые и рыночные расчёты не зависят от вызова генеративной модели.',diagram=[['Авторизованный кандидат\nрезюме / opt-in PR','Работодатель\nсвоя вакансия / условия'],['Rust / ownership + CAS\nснимок / ответы / reviewer','Public GitHub\nREST / GraphQL'],['Ролевая матрица\nзнания + практика','Typed GraphSAGE\nобучаемый routing'],['Парные намерения\nBeta / Fréchet / цензура','Market Intelligence\nотрасль / роль / грейд'],['Цифровой двойник\nусловия / provenance','Человек\nаттестация / найм']]),
        section('2. GitHub как выбранное доказательство','Кандидат явно выбирает публичный PR для целевого резюме и соглашается использовать этот артефакт в оценке. Импортированы до 30 репозиториев аккаунта; для выбранного репозитория — до 30 последних коммитов и 30 обновлённых PR. Защита использует до 50 файлов, 50 коммитов, по 20 элементов conversation/review/inline-review. Ограничения пагинации отображаются, отсутствующий patch не подменяется реконструкцией.','Repository Discussions поддержаны отдельным ограниченным GraphQL-адаптером: до 10 обсуждений и 10 комментариев. Без предоставленного оператором токена состояние token_required. Обсуждение самого PR реально читается через REST без выдуманных разрешений. Внешние ответы ограничены 1,5 МБ, redirects отключены, origin фиксирован, API quotas сохранены. Телефоны и электронные контакты не используются для ранжирования; сбор контактной базы не является назначением интеграции.'),
        section('3. Привязка аккаунта и доказательства','Контроль аккаунта подтверждается одноразовым публичным gist: 64-символьный код, proofit-claim.txt, срок 600 секунд, соответствие GitHub ID владельца и однократное потребление хеша в транзакции. GitHub ID может быть привязан только к одной учётной записи платформы. Публичный gist после проверки можно удалить. Это доказательство контроля аккаунта, а не самостоятельное доказательство авторства кода.','Снимок фиксирует head SHA, изменённые файлы, коммиты и обсуждение. Head проверяется до и после чтения; движение во время импорта отвергается. SHA-256 канонического снимка связывает вопрос, фрагмент изменений и экспертную оценку. Детерминированный artifact-aware агент строит вопросы по имени файла, hunk, изменённым строкам и конкретному критерию роли. Полученный из репозитория текст не интерпретируется как управляющие инструкции.'),
        section('4. Независимая защита личного вклада','Кандидат отвечает на все вопросы, не менее 40 байт содержательного текста на ответ. Ключ ответа обязан совпадать с ID вопроса; посторонние вопросы, пропущенные ответы и stale revision отвергаются. Отправка переводит draft в submitted; повтор не продвигает состояние. Только заранее одобренный независимый эксперт может вынести оценку; самопроверка запрещена.','При аттестации проверяется привязка GitHub ID автора PR или коммитов выбранного PR. Само совпадение идентичности не считается доказательством компетенции: эксперт сверяет объяснение с изменениями, тестами, альтернативами и ответственностью автора. Текущий head проверяется до блокировки БД, затем транзакционно сверяются версия и digest. Новая версия PR требует новой защиты. Сертификат выпускается лишь при достаточной практике, действующей области знаний роли, ясном review lifecycle и соблюдении cooldown.'),
        section('5. Матрицы профессий вместо общей сертификации','Авторские матрицы отображены на профессиональные описания O*NET с атрибуцией. Это не сертификат O*NET, не воспроизведение SFIA и не утверждение об одобрении источником. Для software engineering проверяются корректность, тестирование, проектирование и эксплуатационная безопасность. Для Data Science — статистическая постановка, независимая валидация, воспроизводимость и применимость. Для Data Engineering — семантика, надёжность потока, SQL/вычисления и lineage. Для ML engineering/MLOps — качество модели, serving, жизненный цикл и исполнимая проверка.','Шкала практики 0–4: отсутствие наблюдения; работа по контракту; самостоятельное решение; системные компромиссы и ответственность; независимо проверенный системный результат. Минимумы Junior/Middle/Senior — соответственно 1/2/3 по каждому обязательному критерию, а не усреднение сильных сторон с провалом обязательного барьера. Лидерские позиции требуют отдельного доказательства лидерства и не повышаются автоматически.','CAT подтверждает только role-knowledge: результаты ролевых вопросов и непосредственно проверенные навыки. scope=role-reviewed отделяет знания от полного практического подтверждения. В жёстких ограничениях назначения полное подтверждение роли требует role-reviewed. В подписанном паспорте область сертификата передаётся явно; редактирование резюме не повышает неизменяемый результат.'),
        section('6. Подозрительные паттерны как повод для разбора','Контролируются быстрые правильные последовательности, практически идентичное серверное время и сочетание малой ожидаемой вероятности с быстрым успехом. Пороговая модель авторская, не популяционно откалиброванная. Сигналы сохраняются в независимую очередь review_cases, не объявляют плагиат, не отзывают прежние сертификаты и не выполняют кадровую санкцию.','Разбор учитывает доступность интерфейса, сетевую буферизацию, знакомство с предметом и точность инструментирования. Неблагоприятный вывод требует одобренного независимого reviewer и проверяемого основания. Пользователь вправе оспорить вывод; ранее установленный факт сохраняется до независимого пересмотра. Проверка знаний с сигналом требует подтверждения контекста, а не автоматически становится профессиональной аттестацией.'),
        section('7. Parallel-form A/B и защита от ложной эквивалентности','Тренировка использует стабильное hash-randomization в блоке роли. В role-parameter-forms-v1 форма B изменяет параметры авторских задач и порядок вариантов ответа; общие anchor families сохраняются побайтно при одинаковом seed. Исполнимые правильные ответы пересчитываются для новых параметров. Это две поверхности одного конструкта, а не имитация альтернативной формы через одно переименование. Аттестация не переключается на экспериментальную форму. Наличие A/B само по себе не доказывает равную сложность или пригодность для сертификации.','Диагностика исторической тренировки использует Welch TOST, границу 0,2 и десять запланированных просмотров: alpha=0,005. Отсутствие значимости не называется эквивалентностью. Независимый protocol role/grade/version использует отдельный paired TOST, один финальный анализ alpha=0,05, counterbalanced AB/BA и общие якоря. Нужны минимум 120 завершённых пар, по 40 в порядке AB/BA, эквивалентные theta и anchors, и отсутствие SRM по exact binomial test p≥0,01. Временной интервал между формами не менее 48 часов — организационный барьер, не доказательство отсутствия переноса обучения. Производственная активация требует независимого ролевого исследования, экспертного review и публикации версии.'),
        section('8. Двустороннее решение в двух стадиях','Намерение по вакансии и намерение по офферу записываются раздельно. Кандидат управляет только своей стороной пары; работодатель — только своей вакансией и существующим участником процесса. Для offer требуется связанное приглашение. Запись намерения не подменяет отклик, приглашение или принятие предложения.','Для каждой стадии используется общий cohort завершённых пар: Beta(1,1) обновляется бинарными решениями с 90%-интервалом. Неполные пары цензурируются и не считаются отказом. Совместные границы Фреше не предполагают независимость; точечная совместная оценка появляется только при парных наблюдениях. Самоотбор и отсутствие временного holdout отмечаются явно. Вероятность намерения не называется вероятностью трудоустройства.'),
        section('9. Цифровой двойник под неопределённостью','Двойник соединяет версию рабочих условий, текущий инвентарь возможностей, временную надёжность доказательств и интервальный сценарий решения. Оптимальное распределение сохраняет жёсткие ограничения роли, доказательств и зарплаты; один кандидат не занимает два места. Next proof приоритизирует адресную проверку пробела, а не выдаёт недостающую компетенцию.','Вычислительный модуль robust_twin строит downside-bound и Pareto-фронтир по явно заданным альтернативам бюджета и допущениям. Это сценарный инструмент, не причинная оценка роста вероятности от повышения оплаты. До появления подтверждённых альтернатив живой экран показывает парные базовые оценки, не выдумывает uplift. Компания и кандидат подтверждают результаты сотрудничества отдельно на контрольных точках 30/60/90.'),
        section('10. Полноценный обучаемый графовый слой','Два GraphSAGE-слоя используют отдельные ветви self, supports и transfers_to, hidden=16, нелинейности tanh и сигмоидальную routing-head. Все '+str(n['parameter_count'])+' параметров обучены backprop + Adam; бинарный npz и manifest SHA-256 сохранены. Проверены аналитические градиенты всех шести групп параметров независимыми конечными разностями. Имя, контакты и чувствительные атрибуты не являются признаками.','Граф происхождения остаётся источником наблюдаемых связей. Нейросеть учит структурный routing-score на контролируемом teacher, а не наличие компетенции и не исход найма. Hard requirements и доказанность имеют приоритет перед routing; повреждённый артефакт приводит к явному PageRank fallback. Прежний PageRank сохранён как аудируемый baseline, не выдан за нейросеть.','Обучение: '+str(n['train_graphs'])+' графов; независимый holdout: '+str(n['holdout_graphs'])+' графов и '+str(n['holdout_nodes'])+' узлов. MAE='+format(n['mae'],'.6f')+', RMSE='+format(n['rmse'],'.6f')+'. Это точность аппроксимации структурного teacher на seed-disjoint графах; нет реальных hiring labels, временного рыночного holdout или утверждения о superior hiring accuracy.'),
        section('11. Market Intelligence для конкретной вакансии','Опубликованные вакансии группируются по роли, грейду и отрасли компании. Уникальность определяется нормализованным названием и компанией; показываются медианная вилка, новые записи за семь дней и число синтетических записей. Пул кандидатов использует опубликованные searchable-резюме с согласиями и исключает employment_blocked; его область — роль/грейд, а не отрасль.','Медианное ожидание, размер пула и наблюдаемый срок ответа помогают диагностировать условия. Снимок по компании/роли/грейду/отрасли сохраняется ежедневно, но тренд доступен только после нескольких дат. Это инвентарь платформы, не репрезентативная национальная статистика и не агрегация всех вакансий рынка. Нет вывода о календарном сроке найма по одной записи.','IMOEX и отраслевые индексы не публикуются из ISS без прав использования: MOEX прямо требует договор для продуктов и услуг третьим лицам. licensing_required обеспечивает нулевое влияние на ranking и forecast. Подключение экономического контекста предусматривает независимую temporal ablation: оценку добавочной точности и калибровки, а не предположение, что индекс обязательно полезен.'),
        section('12. Надёжность работодателя без наказания за неизвестность','Отдельно представлены проверка идентичности, наблюдение ответа на отклик в семидневном окне, участие работодателя в контрольной точке 30 дней и двусторонняя фиксация 90 дней. Для каждой оси — Beta-binomial posterior, знаменатель, цензура и нижняя 90%-граница. Composite использует только оси с минимум десятью завершёнными наблюдениями.','Недостаток данных даёт unknown, а не нулевую репутацию. Контрольная точка показывает участие в проверке, не удовлетворённость и не качество трудоустройства. Подтверждённые Dream Job отзывы сотрудников представлены отдельным источником с датой и числом отзывов; они не повышают компетентность кандидата и не заменяются выдуманным рейтингом.'),
        section('13. Воспроизводимые измерения расширения','Контроль выполняется без LLM, с фиксированным seed и сохранёнными JSON/XML протоколами. Числа характеризуют определённые процессы и выборки, а не все реальные случаи найма.',rows=[['Метрика','Измерение','Область'],['Hash allocation A share',format(m['variant_a_share']*100,'.2f')+'% / n=10 000','Контролируемые идентичности, один блок'],['90% interval coverage',format(m['posterior_interval_coverage']*100,'.2f')+'% / n=5 000','Binomial n=120; simulated truths'],['Fréchet violations',str(m['frechet_bound_violations']),'5 000 независимых численных случаев'],['GNN permutation max |Δ|',format(m['permutation_max_score_difference'],'.3g'),'100 графов / 2 000 узлов'],['GNN complete inference P95',format(m['end_to_end_gnn_p95_ms'],'.3f')+' ms','Подготовка tensors + inference; графы по 20 узлов'],['GNN teacher MAE',format(n['mae'],'.6f'),'80 seed-disjoint контрольных графов'],['TOST controlled p',format(m['controlled_tost']['tost_p'],'.3g'),'По 1 000 наблюдений, не human equating'],['Shifted control rejected',str(m['shifted_control_rejected']),'Заданный сдвиг +0,5'],['Real GitHub public read',str(g['files'])+' файлов / '+str(g['pr_commits'])+' коммит / '+str(g['questions'])+' вопроса','Реальный REST, без вывода об авторстве']]),
        section('14. Проверка исполнимого контура','Наборы тестов перечислены отдельно без повторного суммирования перезапусков. Проверена фактическая выдача role-reviewed после независимого review, отказ обычному работодателю, скрытые ответы, CAS, ownership, общий cohort и stage separation. Сквозной GitHub сценарий использует реальное чтение публичного PR и одноразовые синтетические identity/score fixtures; не имитирует аттестацию реального автора.',rows=[['Протокол','Тестов','Результат']]+suites),
        section('15. Ограниченная нагрузка новых методов','Своя нагрузочная выборка: '+str(load['concurrent_sessions'])+' авторизованных сессий, '+str(load['requests'])+' запросов, '+str(load['errors'])+' ошибок; P95='+format(load['p95_ms'],'.2f')+' ms, P99='+format(load['p99_ms'],'.2f')+' ms, throughput='+format(load['throughput_rps'],'.2f')+' req/s. Десять секунд, потолок 40 req/s, warm-up, реальные Rust gateway/PostgreSQL/numerical engine. Проверены workspace, role matrix, graph, market, reliability и bilateral. Нет внешних API, OCR, Docker-задач или LLM в workload. Числа не экстраполируются на миллионы сессий.'),
        section('16. Контроль локализации как граница доверия','Русский, английский, казахский, узбекский, азербайджанский и белорусский доступны в переключателе. У каждого нерусского статического каталога полный набор ключей, без пустых значений и структурных нарушений. Проверяются числа, операторы, плейсхолдеры, технические имена и алфавит. UZ/AZ/BE прошли агентскую вычитку полного каталога; исправлены прежние ошибки в согласиях, контактах, статусах проверки и зарплатных границах. EN/KK сохраняют отдельный проверенный critical-copy срез. Source/catalog SHA-256 привязывают реестр проверки к точной версии строк: изменение каталога отменяет прежний допуск. Независимая человеческая лингвистическая экспертиза не заявляется.','Язык интерфейса не изменяет ID, URL, ответы, ввод или сохранённый артефакт. Код и объяснения PR имеют явную границу no-translate. Произвольный API/LLM-контент и пользовательские документы не входят в покрытие статического каталога. Ролевая оценка требует отдельной методической проверки, если меняется язык заданий: перевод UI не считается psychometric equating.',rows=locale_rows),
        section('17. Источники и границы исследовательского вывода','Включены первичные научные работы, официальные API, профессиональные описания и условия использования. Критерии выбора: применимость к реализованному методу, возможность проверки ссылки, ясное различие механизма и эмпирической эффективности. Дата проверки — 10.10.2026. Методические публикации обосновывают устройство алгоритма, но не доказывают превосходство реализации на данных платформы. Исследования и промышленные платформы полного досье рассмотрены в 09_Global_Research.pdf.',rows=sources),
        section('18. Проспективный ledger и проверяемая вероятность','Владелец вакансии выбирает существующего участника процесса и фиксирует прогноз до первого явно выраженного намерения каждой стороны. Rust самостоятельно вычисляет вероятность из завершённых предыдущих пар, сохраняет роль, грейд, стадию, model version и серверное время. Клиент не задаёт вероятность или исход. В реальной вакансии синтетические участники не входят в обучающий счётчик. Advisory-lock сериализует запись прогноза и намерений для одной пары/стадии; clock_timestamp фиксирует фактическое время после получения блокировки.','Записи prospective_predictions неизменяемы на уровне PostgreSQL trigger. Когда обе стороны ответили после снимка, отдельно однократно сохраняется первый парный исход в prospective_outcomes. Позднейшее изменение намерения не меняет исход оценки. Отчёт считает Brier=(p−y)², log loss, ECE по десяти фиксированным интервалам и AUC с корректными ties. Одноклассовой выборке AUC не присваивается. Joint point оценивается лишь для снимков с идентифицированной совместной оценкой; coverage показано отдельно. Vacancy/offer и role/grade blocks не смешиваются.','Синтетические записи исключаются, неполные пары считаются цензурированными. Минимум для диагностической достаточности — 120 завершённых пар и 20 наблюдений каждого класса; количество не даёт автоматического допуска к калибровке. Зависимость повторных кандидатов и вакансий сохраняется; отчёт не приписывает этим записям независимый популяционный confidence interval. Online report ограничен 500 снимками, owned export — 5000; превышение явно требует фильтра vacancy/stage или отдельного протокола, а не тихо усекает данные. Намерение не означает трудоустройство.'),
        section('19. Подготовленный экономический источник и проверка добавочной ценности','MOEX-адаптер остаётся выключенным. До сетевого запроса оператор должен предоставить действующий rights manifest с разрешённой областью продукта, contract reference, периодом действия и перечнем индексов. Шаблон имеет approved_by_operator=false. Проверка файла — технический барьер, не самостоятельная юридическая экспертиза договора. Без разрешения HTTP-клиент даже не создаётся.','Подготовлено фиксированное HTTPS чтение основной сессии ISS, без redirects и наследования proxy, timeout 10 s, лимит 1,5 MB, диапазон не более 90 дней и одна страница до 100 строк. Проверяются SECID/TRADEDATE/CLOSE, уникальность даты, положительное конечное значение и принадлежность запрошенному диапазону. Пропуск цены не превращается в ноль; давность последнего значения более семи дней даёт stale. Snapshot связывается с digest ответа и digest прав. Это подготовка контракта, не заявление о живом лицензированном чтении.','Macro ablation отделяет модель до holdout, время прогноза, время публикации признака и последующий исход. Сравнение парное: ΔBrier=Brier(with_macro)−Brier(baseline). 1000 bootstrap-реплик ресэмплируют целые даты, не отдельные строки одной даты. Для предварительного positive gate нужны 120 записей, 30 дат и отрицательная верхняя граница 95%-интервала. Это диагностический predictive gain, не причинный эффект фондового индекса. Forecast/ranking effect остаётся нулевым до независимой проверки и публикации модели.'),
        section('20. Независимый протокол A/B без ретроспективного подбора','Оператор создаёт версионированный протокол до начала сбора: фиксируются role, grade, model version, future observation window, alpha, margin, запланированное число анализов и первичная метрика. SHA-256 фиксирует контракт; независимая preregistration требует отдельной публикации протокола с проверяемой датой. Файл хеша сам по себе не доказывает происхождение человеческих наблюдений.','Private form-bundle генерирует обе формы с фиксированным role/grade/version seed и одинаковыми якорями. Он содержит закрытые ключи и предназначен оператору, не публичному API кандидата. Независимая выборка использует counterbalanced AB/BA по стабильному распределению. Проверяются отсутствие повторных участников, единая роль/грейд/версия, окно протокола, интервал 48 h, конечные scores, разные digest форм и digest первичного источника. Синтетические, незавершённые и требующие контекстного review записи исключаются с раздельными счётчиками. Это не отменяет review сигнала и не объявляет нарушение.','При статистическом gate=true production_activation_allowed остаётся false: дальнейшее решение требует одобренного независимого эксперта, проверки заданий и версионированной публикации. Тренировка с индивидуальным seed не подменяет independent equating. Код, источник данных и предмет профессиональной аттестации разделены.'),
        section('21. Измерения завершённого программного контура','Прицельные CPU/HTTP/browser протоколы проверяют изменённые компоненты. Старые workload, forecasting и retrieval измерения не перезапускались и сохраняют собственную дату. Ни одно число ниже не названо реальным эффектом найма.',rows=[['Контроль','Результат','Знаменатель'],['Proper scoring oracle |ΔBrier|',str(final['brier_oracle_absolute_error']),str(final['proper_score_oracle_cases'])+' controlled predictions'],['Proper scoring oracle |ΔLogLoss|',str(final['log_loss_oracle_absolute_error']),str(final['proper_score_oracle_cases'])+' controlled predictions'],['Future-label leakage rejection',str(final['future_label_leakage_rejections'])+'/'+str(final['future_label_leakage_controls']),'Преднамеренно нарушенная хронология'],['Paired TOST positive control',str(final['paired_equivalence_positive_control']),'200 controlled paired observations'],['Shift +0,5 negative control',str(final['shifted_form_negative_control_rejected']),'200 controlled paired observations'],['Macro paired-loss oracle |Δ|',format(final['macro_paired_loss_oracle_absolute_error'],'.3g'),'160 controlled rows / 40 dates'],['CPU report P95',format(final['cohort_report_cpu']['p95_ms'],'.3f')+' ms','120 records; 5 warm-up + 40 timed runs'],['Static locale coverage','1544/1544 × 5','EN/KK/UZ/AZ/BE; 0 structural errors']]),
    ])
